var i=`0810-chikanda`;var n=`world-0810`;var t=`ZM`;var s=`eastern-africa`;var r=8;var l=81;var o={en:`Chikanda`,ua:`Чіканда`};var d={en:`Chikanda is a Zambia dish made with peanut butter, ground egusi, cornmeal, banana leaf. This home-scale recipe assigns measured ingredients to the steps where they are used. Chikanda-inspired vegetarian loaf: orchid tubers, the defining traditional base, are absent. Ground egusi and cornmeal are not equivalent substitutes.`,ua:`Чіканда, страва кухні країни Замбія. Основні складники: арахісова паста, мелене егусі, кукурудзяна крупа дрібного помелу, банановий лист. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Страва лише за мотивами чіканди: у каталозі немає традиційних бульб орхідей. Егусі й кукурудзяне борошно не є рівноцінною заміною.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`peanut-butter`,170,`g`],[`ground-egusi`,230,`g`],[`cornmeal`,140,`g`],[`water`,260,`ml`],[`table-salt`,4,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[[`banana-leaf`,5,`leaf`]]},{en:`Wrap the thick mixture securely in clean food-grade banana leaves, then steam until set all the way through; this is only a chikanda-inspired loaf.`,ua:`Щільно загорніть густу масу в чисте харчове бананове листя та пропарте до повного ущільнення; це лише страва за мотивами чіканди.`,t:[`steaming`],m:55,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`hot-paprika`,2,`g`]]}];var g={slug:i,id:n,country:`ZM`,region:s,servings:8,minutes:81,title:o,text:d,steps:u};export{t as country,g as default,n as id,l as minutes,s as region,r as servings,i as slug,u as steps,d as text,o as title};